namespace Microsoft.Agents.AI;

/// <summary>
/// An <see cref="AIContextProvider"/> that gives agents the ability to maintain a persistent todo list within a session.
/// </summary>
/// <remarks>
/// <para>
/// The provider exposes five function tools to the agent — <c>AddTodos</c>, <c>CompleteTodos</c>, <c>RemoveTodos</c>,
/// <c>GetRemainingTodos</c> and <c>GetAllTodos</c> — that allow the model to plan and track multi-step work.
/// </para>
/// <para>
/// State is stored in the <see cref="AgentSession.StateBag"/> under the key <c>"TodoProvider"</c> and therefore persists
/// across multiple invocations of the same session. Because the provider is stateless with respect to its own instance
/// fields, a single <see cref="TodoProvider"/> can be shared across many sessions.
/// </para>
/// </remarks>
public sealed class TodoProvider : AIContextProvider
{
    /// <summary>The key used to store the todo state in the session's <see cref="AgentSessionStateBag"/>.</summary>
    private const string StateKeyName = "TodoProvider";

    private const string DefaultInstructions =
        "You have access to a persistent todo list to help you plan and track multi-step tasks. " +
        "Use the AddTodos tool to record tasks you intend to perform, CompleteTodos to mark tasks as done once finished, " +
        "RemoveTodos to delete tasks that are no longer relevant, GetRemainingTodos to review outstanding work, " +
        "and GetAllTodos to review the full list. Keep the todo list up to date as you make progress.";

    private readonly ProviderSessionState<TodoState> _sessionState;
    private IReadOnlyList<string>? _stateKeys;

    /// <summary>
    /// Initializes a new instance of the <see cref="TodoProvider"/> class.
    /// </summary>
    public TodoProvider()
    {
        this._sessionState = new ProviderSessionState<TodoState>(
            _ => new TodoState(),
            StateKeyName,
            AgentJsonUtilities.DefaultOptions);
    }

    /// <inheritdoc />
    public override IReadOnlyList<string> StateKeys => this._stateKeys ??= [this._sessionState.StateKey];

    /// <inheritdoc />
    protected override ValueTask<AIContext> ProvideAIContextAsync(AIContextProvider.InvokingContext context, CancellationToken cancellationToken = default)
    {
        _ = Throw.IfNull(context);

        var session = context.Session;

        AITool[] tools =
        [
            AIFunctionFactory.Create(
                (List<TodoItemInput> todos) => this.AddTodos(session, todos),
                new AIFunctionFactoryOptions
                {
                    Name = "AddTodos",
                    Description = "Adds one or more items to the todo list. Each item is assigned a unique integer id.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
            AIFunctionFactory.Create(
                (List<int> ids) => this.CompleteTodos(session, ids),
                new AIFunctionFactoryOptions
                {
                    Name = "CompleteTodos",
                    Description = "Marks the todo items with the given ids as complete. Returns the number of items updated.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
            AIFunctionFactory.Create(
                (List<int> ids) => this.RemoveTodos(session, ids),
                new AIFunctionFactoryOptions
                {
                    Name = "RemoveTodos",
                    Description = "Removes the todo items with the given ids from the list. Returns the number of items removed.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
            AIFunctionFactory.Create(
                () => this.GetRemainingTodos(session),
                new AIFunctionFactoryOptions
                {
                    Name = "GetRemainingTodos",
                    Description = "Gets the todo items that have not yet been completed.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
            AIFunctionFactory.Create(
                () => this.GetAllTodosList(session),
                new AIFunctionFactoryOptions
                {
                    Name = "GetAllTodos",
                    Description = "Gets all todo items regardless of their completion status.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
        ];

        return new ValueTask<AIContext>(new AIContext
        {
            Instructions = DefaultInstructions,
            Tools = tools,
        });
    }

    /// <summary>
    /// Gets all todo items stored for the specified session.
    /// </summary>
    /// <param name="session">The session whose todo items should be retrieved, or <see langword="null"/>.</param>
    /// <returns>A read-only list containing all todo items. Returns an empty list for a session with no prior state.</returns>
    public IReadOnlyList<TodoItem> GetAllTodos(AgentSession? session)
        => this._sessionState.GetOrInitializeState(session).Items;

    /// <summary>
    /// Gets the todo items that have not yet been completed for the specified session.
    /// </summary>
    /// <param name="session">The session whose todo items should be retrieved, or <see langword="null"/>.</param>
    /// <returns>A list containing only the todo items where <see cref="TodoItem.IsComplete"/> is <see langword="false"/>.</returns>
    public List<TodoItem> GetRemainingTodos(AgentSession? session)
        => this._sessionState.GetOrInitializeState(session).Items.Where(item => !item.IsComplete).ToList();

    /// <summary>Adds one or more items to the todo list, assigning each an auto-incrementing id.</summary>
    private List<TodoItem> AddTodos(AgentSession? session, List<TodoItemInput> todos)
    {
        var state = this._sessionState.GetOrInitializeState(session);

        var added = new List<TodoItem>();
        if (todos is not null)
        {
            foreach (var input in todos)
            {
                if (input is null)
                {
                    continue;
                }

                var item = new TodoItem
                {
                    Id = state.NextId++,
                    Title = input.Title ?? string.Empty,
                    Description = input.Description,
                    IsComplete = false,
                };

                state.Items.Add(item);
                added.Add(item);
            }
        }

        this._sessionState.SaveState(session, state);

